pragma solidity ^0.8.0;

import "../libraries/Bitmask.sol";

contract LuminexPrivacyPolicy {
    using Bitmask for uint256;

    enum PrivacyPolicy {
        Reveal
    }

    mapping(address => mapping(address => uint256)) internal grantedAccess;

    function grant(address to, PrivacyPolicy accessType) public {
        uint256 accessIndex = uint256(accessType);

        require(!grantedAccess[msg.sender][to].get(accessIndex), "Access already granted");
        grantedAccess[msg.sender][to] = grantedAccess[msg.sender][to].set(accessIndex);
    }

    function revoke(address from, PrivacyPolicy accessType) public {
        uint256 accessIndex = uint256(accessType);

        require(grantedAccess[msg.sender][from].get(accessIndex), "No access granted yet");
        grantedAccess[msg.sender][from] = grantedAccess[msg.sender][from].unset(accessIndex);
    }

    function hasAccess(address owner, address accessor, PrivacyPolicy accessType) internal view returns (bool) {
        return grantedAccess[owner][accessor].get(uint256(accessType));
    }
}","keccak256":"0x56ae92341e8d6304666372ece6554064f6dd7fb214532c34969e031b735f93d9","license":"BUSL-1.1"},"contracts/test/mocks/MockIluminexDEX/contracts/confidentialERC20/PrivateERC20.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import "./ERC2771Context.sol";
import "./LuminexPrivacyPolicy.sol";
import "./BalanceRegistry.sol";

contract PrivateERC20 is IERC20, ERC2771Context, LuminexPrivacyPolicy {
    struct PrivateERC20Config {
        bool totalSupplyVisible;
        string name;
        string symbol;
        uint8 decimals;
    }

    mapping(address => uint256) internal _balances;
    mapping(address => mapping(address => uint256)) internal _allowances;

    string public name;
    string public symbol;
    uint8 public decimals;

    bool public immutable totalSupplyVisible;
    ConfidentialBalanceRegistry public immutable balanceRegistry;

    uint256 internal _globalTotalSupply;

    constructor(
        PrivateERC20Config memory _config,
        address _multicall,
        ConfidentialBalanceRegistry _balanceRegistry
    ) ERC2771Context(_multicall) {
        name = _config.name;
        symbol = _config.symbol;
        decimals = _config.decimals;
        totalSupplyVisible = _config.totalSupplyVisible;
        balanceRegistry = _balanceRegistry;
    }

    function _isAllowedByPrivacyPolicy(
        address owner
    ) private view returns (bool) {
        return
            _msgSender() == owner ||
            msg.sender == address(this) ||
            hasAccess(
                owner,
                _msgSender(),
                LuminexPrivacyPolicy.PrivacyPolicy.Reveal
            ) ||
            msg.sender == address(balanceRegistry);
    }

    function totalSupply() public view virtual override returns (uint256) {
        return totalSupplyVisible ? _globalTotalSupply : 0;
    }

    function balanceOf(
        address account
    ) public view virtual override returns (uint256) {
        // if (!_isAllowedByPrivacyPolicy(account)) {
        //     return 0;
        // }

        return _balances[account];
    }

    function allowance(
        address owner,
        address spender
    ) public view virtual override returns (uint256) {
        // if (!_isAllowedByPrivacyPolicy(owner)) {
        //     return 0;
        // }

        // if (_allowances[owner][spender] > 0 && _msgSender() == spender) {
        //     return _allowances[owner][spender];
        // }

        return _allowances[owner][spender];
    }

    function _approve(address owner, address spender, uint256 amount) internal {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");

        _allowances[owner][spender] = amount;
    }

    function approve(
        address spender,
        uint256 amount
    ) public virtual override returns (bool) {
        address owner = msg.sender;
        _approve(owner, spender, amount);
        return true;
    }

    function _spendAllowance(
        address owner,
        address spender,
        uint256 amount
    ) internal virtual {
        uint256 currentAllowance = _allowances[owner][spender];
        if (currentAllowance != type(uint256).max) {
            require(
                currentAllowance >= amount,
                "ERC20: insufficient allowance"
            );
            unchecked {
                _approve(owner, spender, currentAllowance - amount);
            }
        }
    }

    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        uint256 fromBalance = _balances[from];
        require(
            fromBalance >= amount,
            "ERC20: transfer amount exceeds balance"
        );
        unchecked {
            _balances[from] = fromBalance - amount;
        }

        _balances[to] += amount;
        balanceRegistry.onTransfer(to, from, _balances[from]);
    }

    function transfer(
        address to,
        uint256 amount
    ) public virtual override returns (bool) {
        address owner = msg.sender;
        _transfer(owner, to, amount);
        return true;
    }

    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) public virtual override returns (bool) {
        address spender = msg.sender;
        _spendAllowance(from, spender, amount);
        _transfer(from, to, amount);
        return true;
    }

    function _mint(address to, uint256 amount) internal {
        _balances[to] += amount;
        _globalTotalSupply += amount;

        balanceRegistry.onTransfer(to, address(0), 0);
    }

    function _burn(address from, uint256 amount) internal {
        _balances[from] -= amount;
        _globalTotalSupply -= amount;

        balanceRegistry.onTransfer(address(0), from, _balances[from]);
    }
}
