pragma solidity ^0.8.0;

library Bitmask {
    function get(uint256 bitmap, uint256 index) internal pure returns (bool) {
        uint256 mask = 1 << (index & 0xff);
        return bitmap & mask != 0;
    }

    function setTo(uint256 bitmap, uint256 index, bool value) internal pure returns (uint256) {
        if (value) {
            return set(bitmap, index);
        } else {
            return unset(bitmap, index);
        }
    }

    function set(uint256 bitmap, uint256 index) internal pure returns (uint256) {
        uint256 mask = 1 << (index & 0xff);
        return bitmap | mask;
    }

    function unset(uint256 bitmap, uint256 index) internal pure returns (uint256) {
        uint256 mask = 1 << (index & 0xff);
        return bitmap & ~mask;
    }
}","keccak256":"0x91af3e69974186e2aab30ef5223b4d7e433b6cffc4ad6bb77f178428c437b74a","license":"BUSL-1.1"},"contracts/test/mocks/MockIluminexDEX/contracts/libraries/FeesCollector.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import "../illuminex/op/celer/safeguard/Ownable.sol";

contract FeesCollector is Ownable {
    uint256 private _feesCollected;

    event FeesCollected(address indexed to, uint256 amount);
    event FeesDeposited(uint256 amount);

    function collectFees(address payable to, uint256 amount) public onlyOwner {
        require(amount <= _feesCollected, "Insufficient fees collected");

        _feesCollected -= amount;
        to.transfer(amount);

        emit FeesCollected(to, amount);
    }

    function _depositFees(uint256 amount) internal {
        _feesCollected += amount;
        emit FeesDeposited(amount);
    }
}
